package main

// Generated from web/index.html. Keeping the page as a Go string avoids requiring
// the Go 1.16 embed package while retaining a self-contained executable.
const htmlTemplateContent = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>LumaChat</title>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/highlight.js@11.9.0/styles/github.min.css\">\n<script src=\"https://cdn.jsdelivr.net/npm/marked@12.0.2/marked.min.js\"></script>\n<script src=\"https://cdn.jsdelivr.net/npm/highlight.js@11.9.0/lib/common.min.js\"></script>\n<script src=\"https://cdn.jsdelivr.net/npm/dompurify@3.1.6/dist/purify.min.js\"></script>\n<style>\n:root{--blue:#1a73e8;--bg:#f8f9fa;--surface:#fff;--text:#202124;--sub:#5f6368;--border:#dadce0;--danger:#d93025;--ok:#34a853;--hover:#f1f3f4}\n[data-theme=\"dark\"]{--bg:#000;--surface:#000;--text:#e8eaed;--sub:#9aa0a6;--border:#252525;--hover:#171717}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{font-family:sans-serif;background:var(--bg);color:var(--text);display:flex;overflow:hidden;font-size:14px;zoom:1.1}\nbutton{font-family:inherit;cursor:pointer}\ninput,select,textarea{font-family:inherit}\n.modal{position:fixed;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;z-index:999;backdrop-filter:blur(4px)}\n.modal.hidden{display:none}\n.card{background:var(--surface);border-radius:16px;box-shadow:0 12px 32px rgba(0,0,0,.2);max-height:90vh;overflow:hidden;display:flex;flex-direction:column;width:480px}\n.card.wide{width:720px}\n.card-head{padding:20px 24px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}\n.card-head h2{margin:0;font-size:18px;color:var(--blue)}\n.card-body{padding:20px 24px;overflow-y:auto;flex:1}\n.card-foot{padding:14px 24px;border-top:1px solid var(--border);display:flex;gap:10px;justify-content:flex-end;background:var(--bg)}\n.field{margin-bottom:14px}\n.field label{display:block;font-size:12px;color:var(--sub);margin-bottom:6px;font-weight:500}\n.field input,.field select,.field textarea{width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text);font-size:14px;outline:none;transition:border-color .15s}\n.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--blue)}\n.btn{padding:9px 18px;border-radius:8px;border:none;background:var(--blue);color:#fff;font-size:14px;font-weight:500;transition:opacity .15s}\n.btn:hover{opacity:.9}\n.btn:disabled{background:#9aa0a6;cursor:not-allowed}\n.btn.ghost{background:transparent;color:var(--text);border:1px solid var(--border)}\n.btn.ghost:hover{background:var(--hover)}\n.btn.danger{background:var(--danger)}\n.btn.ok{background:var(--ok)}\n.btn.sm{padding:6px 12px;font-size:12px}\n.link{color:var(--blue);cursor:pointer;font-size:13px}\n.link:hover{text-decoration:underline}\n#sidebar{width:280px;background:var(--surface);border-right:1px solid var(--border);display:flex;flex-direction:column;flex-shrink:0}\n.side-head{padding:10px 12px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px}.side-head .brand{display:none}\n.brand{font-weight:700;color:var(--blue);font-size:16px;flex:1}\n.side-body{flex:1;overflow-y:auto;padding:10px}\n#session-list{display:flex;flex-direction:column;gap:2px}\n.session-row{display:flex;align-items:center;padding:10px 12px;border-radius:8px;cursor:pointer;font-size:13px;color:var(--text);gap:6px}\n.session-row:hover{background:var(--hover)}\n.session-row.active{background:rgba(26,115,232,.12);color:var(--blue);font-weight:500}\n.session-title{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.session-menu{opacity:0;border:none;background:transparent;color:var(--sub);padding:2px 6px;border-radius:4px;font-size:14px}\n.session-row:hover .session-menu{opacity:1}\n.session-menu:hover{background:rgba(0,0,0,.08)}\n#main{flex:1;display:flex;flex-direction:column;background:var(--surface);min-width:0}\n.topbar{padding:12px 20px;border-bottom:1px solid var(--border);display:flex;gap:12px;align-items:center;flex-shrink:0}\n.topbar select{padding:7px 12px;border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--text);font-size:13px}\n.topbar .spacer{flex:1}\n.icon-btn{background:transparent;border:1px solid var(--border);color:var(--text);width:34px;height:34px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:16px}\n.icon-btn:hover{background:var(--hover)}\n#chat-box{flex:1;overflow-y:auto;padding:24px;display:flex;flex-direction:column;gap:18px;scroll-behavior:smooth}\n.msg{max-width:min(760px,80%);line-height:1.65;font-size:15px;word-wrap:break-word;position:relative;padding:14px 18px;border-radius:14px}\n.msg.user{align-self:flex-end;background:rgba(26,115,232,.1);color:var(--text);white-space:pre-wrap}\n.msg.assistant{align-self:flex-start;background:transparent;border:0;padding-left:0;padding-right:0}\n.msg.assistant.error{background:rgba(217,48,37,.08);border-color:rgba(217,48,37,.3);color:var(--danger)}\n.msg-tools{position:absolute;top:-10px;right:8px;display:flex;gap:4px;opacity:0;transition:opacity .15s}\n.msg:hover .msg-tools{opacity:1}\n.msg-tools button{background:var(--surface);border:1px solid var(--border);color:var(--sub);width:26px;height:26px;border-radius:50%;font-size:12px;display:flex;align-items:center;justify-content:center}\n.msg-tools button:hover{color:var(--blue);border-color:var(--blue)}\n.msg.assistant p{margin:0 0 10px}\n.msg.assistant p:last-child{margin-bottom:0}\n.msg.assistant pre{background:#f6f8fa;border:1px solid var(--border);border-radius:8px;padding:0;overflow:hidden;margin:10px 0;position:relative}\n[data-theme=\"dark\"] .msg.assistant pre{background:#1e1e1e}\n.code-head{display:flex;justify-content:space-between;align-items:center;padding:6px 12px;background:rgba(0,0,0,.04);border-bottom:1px solid var(--border);font-size:12px;color:var(--sub)}\n[data-theme=\"dark\"] .code-head{background:rgba(255,255,255,.04)}\n.code-head .lang{font-weight:600}\n.code-head button{background:none;border:none;color:var(--blue);cursor:pointer;font-size:12px}\n.code-head button:hover{text-decoration:underline}\n.msg.assistant pre code{display:block;padding:12px 14px;overflow-x:auto;font-family:'SF Mono',Consolas,'Courier New',monospace;font-size:13px;line-height:1.5}\n.msg.assistant :not(pre)>code{background:rgba(0,0,0,.06);padding:2px 6px;border-radius:4px;font-family:'SF Mono',Consolas,monospace;font-size:13px}\n[data-theme=\"dark\"] .msg.assistant :not(pre)>code{background:rgba(255,255,255,.08)}\n.msg.assistant table{border-collapse:collapse;margin:10px 0;font-size:13px}\n.msg.assistant th,.msg.assistant td{border:1px solid var(--border);padding:6px 10px}\n.msg.assistant th{background:var(--hover)}\n.msg.assistant blockquote{border-left:3px solid var(--border);margin:10px 0;padding:4px 12px;color:var(--sub)}\n.msg.assistant ul,.msg.assistant ol{margin:8px 0;padding-left:22px}\n.msg.assistant a{color:var(--blue)}\n.msg.assistant h1,.msg.assistant h2,.msg.assistant h3{margin:14px 0 8px;line-height:1.3}\n.msg.assistant h1{font-size:20px}.msg.assistant h2{font-size:18px}.msg.assistant h3{font-size:16px}\n.token-info{margin-top:8px;font-size:11px;color:var(--sub);font-style:italic}\n#input-bar{padding:14px 20px;border-top:1px solid var(--border);background:var(--surface);display:flex;gap:10px;align-items:flex-end;flex-shrink:0;flex-wrap:wrap}.composer-options{display:flex;gap:8px;align-items:center;width:100%;padding-left:8px}.mini-toggle{border:1px solid var(--border);border-radius:999px;padding:5px 10px;background:transparent;color:var(--sub);font-size:12px}.mini-toggle.active{border-color:var(--blue);color:var(--blue);background:rgba(26,115,232,.10)}.account-button{display:flex;align-items:center;gap:10px;margin:10px;padding:10px;border:0;border-radius:10px;background:transparent;color:var(--text);text-align:left}.account-button:hover{background:var(--hover)}.account-avatar{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--hover);font-weight:600}.account-more{margin-left:auto;color:var(--sub)}body.sidebar-collapsed #sidebar{width:56px}body.sidebar-collapsed #session-list,body.sidebar-collapsed .side-body>.btn,body.sidebar-collapsed #account-name,body.sidebar-collapsed .account-more{display:none}body.sidebar-collapsed .account-button{justify-content:center;padding:8px 4px}\n.input-wrap{flex:1;background:var(--bg);border:1px solid var(--border);border-radius:14px;padding:8px 14px;display:flex;align-items:center}\n.input-wrap textarea{flex:1;border:none;background:transparent;resize:none;outline:none;color:var(--text);font-size:15px;line-height:1.5;max-height:140px;min-height:22px}\n.send-btn{width:44px;height:44px;border-radius:50%;border:none;background:var(--blue);color:#fff;font-size:18px;display:flex;align-items:center;justify-content:center;transition:opacity .15s}\n.send-btn:disabled{background:#9aa0a6;cursor:not-allowed}\n.send-btn:hover:not(:disabled){opacity:.85}\n.tabs{display:flex;gap:4px;border-bottom:1px solid var(--border);margin-bottom:18px}\n.tab{padding:10px 18px;background:none;border:none;color:var(--sub);font-size:14px;font-weight:500;border-bottom:2px solid transparent;cursor:pointer}\n.tab.active{color:var(--blue);border-bottom-color:var(--blue)}\n.tab-panel{display:none}\n.tab-panel.active{display:block}\n.prov-list{display:flex;flex-direction:column;gap:8px;margin-bottom:18px}\n.prov-item{border:1px solid var(--border);border-radius:10px;padding:12px 14px;background:var(--bg)}\n.prov-item-head{display:flex;align-items:center;gap:8px;margin-bottom:6px}\n.prov-item-head .name{font-weight:600;flex:1;color:var(--text)}\n.prov-item-head .badge{background:rgba(26,115,232,.1);color:var(--blue);padding:2px 8px;border-radius:10px;font-size:11px;font-weight:500}\n.prov-item-body{font-size:12px;color:var(--sub);word-break:break-all}\n.prov-item-actions{display:flex;gap:6px;margin-top:8px}\n.empty{padding:30px;text-align:center;color:var(--sub);font-size:13px;border:1px dashed var(--border);border-radius:10px}\n.model-list{border:1px solid var(--border);border-radius:8px;padding:10px;max-height:200px;overflow-y:auto;background:var(--bg)}\n.model-item{display:flex;align-items:center;gap:8px;padding:5px 4px;font-size:13px}\n.model-item input[type=checkbox]{width:16px;height:16px;cursor:pointer}\n#toast{position:fixed;bottom:30px;left:50%;transform:translateX(-50%);z-index:9999;display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none}\n.toast-item{padding:10px 20px;border-radius:8px;color:#fff;font-size:13px;box-shadow:0 4px 12px rgba(0,0,0,.15);animation:fadein .2s;pointer-events:auto}\n.toast-item.ok{background:var(--ok)}\n.toast-item.err{background:var(--danger)}\n.toast-item.info{background:#3c4043}\n@keyframes fadein{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}\n.dots::after{content:'';animation:dots 1.4s infinite}\n@keyframes dots{0%{content:''}25%{content:'.'}50%{content:'..'}75%{content:'...'}}\n</style>\n</head>\n<body>\n\n<div class=\"modal\" id=\"auth-modal\">\n  <div class=\"card\" style=\"width:400px\">\n    <div class=\"card-head\">\n      <h2 id=\"auth-title\">登录 LumaChat</h2>\n    </div>\n    <div class=\"card-body\">\n      <div class=\"field\"><label>用户名</label><input type=\"text\" id=\"auth-user\" placeholder=\"请输入用户名\" autocomplete=\"username\"></div>\n      <div class=\"field\"><label>密码</label><input type=\"password\" id=\"auth-pass\" placeholder=\"请输入密码\" autocomplete=\"current-password\" onkeydown=\"if(event.key==='Enter')doAuth()\"></div>\n    </div>\n    <div class=\"card-foot\">\n      <span class=\"link\" onclick=\"toggleAuthMode()\" id=\"auth-switch\" style=\"margin-right:auto\">没有账号？去注册</span>\n      <button class=\"btn\" onclick=\"doAuth()\" id=\"auth-btn\">登 录</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"modal hidden\" id=\"settings-modal\">\n  <div class=\"card wide\">\n    <div class=\"card-head\">\n      <h2>设置</h2>\n      <button class=\"icon-btn\" onclick=\"closeSettings()\">✕</button>\n    </div>\n    <div class=\"card-body\">\n      <div class=\"tabs\">\n        <button class=\"tab active\" onclick=\"switchTab('providers',this)\">服务商</button>\n        <button class=\"tab\" onclick=\"switchTab('add-provider',this)\">添加服务商</button>\n        <button class=\"tab\" onclick=\"switchTab('preferences',this)\">偏好设置</button>\n        <button class=\"tab\" onclick=\"switchTab('account',this)\">账号</button>\n      </div>\n\n      <div class=\"tab-panel active\" id=\"tab-providers\">\n        <div class=\"prov-list\" id=\"prov-list\"></div>\n      </div>\n\n      <div class=\"tab-panel\" id=\"tab-add-provider\">\n        <div class=\"field\"><label>服务商名称</label><input type=\"text\" id=\"add-name\" placeholder=\"例如：OpenAI 官方\"></div>\n        <div class=\"field\"><label>API Base URL</label><input type=\"text\" id=\"add-url\" placeholder=\"https://api.openai.com/v1\"></div>\n        <div class=\"field\"><label>API Key</label><input type=\"password\" id=\"add-key\" placeholder=\"sk-...\"></div>\n        <div class=\"field\">\n          <label>操作</label>\n          <div style=\"display:flex;gap:8px\">\n            <button class=\"btn ok sm\" onclick=\"testProvider()\">测试连接</button>\n            <button class=\"btn sm\" onclick=\"fetchModels()\">获取模型列表</button>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label>模型（勾选）</label>\n          <div class=\"model-list\" id=\"model-list\"><div style=\"color:var(--sub);font-size:13px;text-align:center;padding:16px\">点击上方\"获取模型列表\"</div></div>\n        </div>\n      </div>\n\n      <div class=\"tab-panel\" id=\"tab-preferences\">\n        <div class=\"field\" style=\"display:flex;align-items:center;gap:10px\"><input type=\"checkbox\" id=\"pref-dark-theme\" style=\"width:18px;height:18px\"><label for=\"pref-dark-theme\" style=\"margin:0\">纯黑暗色模式</label></div>\n        <div class=\"field\"><label>默认服务商</label><select id=\"settings-prov-select\" onchange=\"onSettingsProvChange()\"></select></div>\n        <div class=\"field\"><label>默认模型</label><select id=\"settings-model-select\" onchange=\"onSettingsModelChange()\"></select></div>\n        <div class=\"field\" style=\"display:flex;align-items:center;gap:10px\">\n          <input type=\"checkbox\" id=\"pref-show-tokens\" style=\"width:18px;height:18px\">\n          <label for=\"pref-show-tokens\" style=\"margin:0\">显示 Token 消耗统计</label>\n        </div>\n        <div class=\"field\" style=\"display:flex;align-items:center;gap:10px\">\n          <input type=\"checkbox\" id=\"pref-disable-think\" style=\"width:18px;height:18px\">\n          <label for=\"pref-disable-think\" style=\"margin:0\">屏蔽思考过程（reasoning）</label>\n        </div>\n        <div class=\"field\" style=\"display:flex;align-items:center;gap:10px\">\n          <input type=\"checkbox\" id=\"pref-disable-web\" style=\"width:18px;height:18px\">\n          <label for=\"pref-disable-web\" style=\"margin:0\">屏蔽联网搜索</label>\n        </div>\n      </div>\n\n      <div class=\"tab-panel\" id=\"tab-account\">\n        <div class=\"field\"><label>当前用户</label><input type=\"text\" id=\"acc-user\" disabled></div>\n        <div class=\"field\"><label>原密码</label><input type=\"password\" id=\"acc-old-pass\" autocomplete=\"current-password\"></div>\n        <div class=\"field\"><label>新密码</label><input type=\"password\" id=\"acc-new-pass\" autocomplete=\"new-password\"></div>\n        <button class=\"btn\" onclick=\"changePassword()\">修改密码</button>\n      </div>\n    </div>\n    <div class=\"card-foot\">\n      <button class=\"btn ghost\" onclick=\"closeSettings()\">关闭</button>\n      <button class=\"btn\" onclick=\"saveAllSettings()\">保存</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"modal hidden\" id=\"rename-modal\">\n  <div class=\"card\" style=\"width:400px\">\n    <div class=\"card-head\"><h2>重命名会话</h2></div>\n    <div class=\"card-body\">\n      <div class=\"field\"><label>新标题</label><input type=\"text\" id=\"rename-input\" maxlength=\"100\"></div>\n    </div>\n    <div class=\"card-foot\">\n      <button class=\"btn ghost\" onclick=\"closeRename()\">取消</button>\n      <button class=\"btn\" onclick=\"confirmRename()\">确定</button>\n    </div>\n  </div>\n</div>\n\n<aside id=\"sidebar\">\n  <div class=\"side-head\"><button class=\"icon-btn\" onclick=\"toggleSidebar()\" title=\"收起侧栏\">☰</button><button class=\"icon-btn\" onclick=\"openSettings()\" title=\"设置\">⚙</button></div>\n  <div class=\"side-body\">\n    <button class=\"btn\" style=\"width:100%;margin-bottom:12px\" onclick=\"createSession()\">＋ 新对话</button>\n    <div id=\"session-list\"></div>\n  </div>\n  <button id=\"account-button\" class=\"account-button\" onclick=\"openSettings()\" title=\"账户与设置\"><span class=\"account-avatar\">U</span><span id=\"account-name\">账户</span><span class=\"account-more\">⋯</span></button>\n</aside>\n\n<div id=\"main\">\n  <div class=\"topbar\"><span id=\"active-chat-title\" style=\"font-size:14px;color:var(--sub)\">新对话</span><div class=\"spacer\"></div></div>\n  <div id=\"chat-box\"></div>\n  <div id=\"input-bar\">\n    <div class=\"input-wrap\">\n      <textarea id=\"prompt-input\" placeholder=\"输入消息，Enter 发送，Shift+Enter 换行\" rows=\"1\" onkeydown=\"onKeyDown(event)\" oninput=\"autoResize(this)\"></textarea>\n    </div>\n    <button class=\"send-btn\" id=\"send-btn\" onclick=\"sendMessage()\">➤</button><div class=\"composer-options\"><button id=\"chat-think-toggle\" class=\"mini-toggle\" onclick=\"toggleChatThink()\" type=\"button\">✧ 思考模式：关</button><button id=\"chat-token-toggle\" class=\"mini-toggle\" onclick=\"toggleChatTokens()\" type=\"button\">Token 统计：关</button></div>\n  </div>\n</div>\n\n<div id=\"toast\"></div>\n\n<script>\nif (typeof marked !== 'undefined' && typeof marked.setOptions === 'function') {\n  marked.setOptions({\n    breaks: true,\n    gfm: true,\n    highlight: function(code, lang) {\n      try {\n        if (typeof hljs !== 'undefined') {\n          if (lang && hljs.getLanguage(lang)) {\n            return hljs.highlight(code, {language: lang, ignoreIllegals: true}).value;\n          }\n          return hljs.highlightAuto(code).value;\n        }\n      } catch(e) {}\n      return String(code).replace(/[&<>]/g, function(c) {\n        return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c];\n      });\n    }\n  });\n}\n\nfunction renderMarkdown(text) {\n  if (!text) return '';\n  var html;\n  if (typeof marked !== 'undefined' && typeof marked.parse === 'function') {\n    html = marked.parse(text);\n  } else {\n    html = '<pre style=\"white-space:pre-wrap\">' + String(text).replace(/[&<>]/g, function(c) {\n      return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c];\n    }) + '</pre>';\n  }\n  return typeof DOMPurify !== 'undefined' && typeof DOMPurify.sanitize === 'function'\n    ? DOMPurify.sanitize(html, {ADD_ATTR: ['target']})\n    : html;\n}\n\nfunction decorateCodeBlocks(container) {\n  container.querySelectorAll('pre').forEach(function(pre) {\n    if (pre.parentNode.classList.contains('code-wrap')) return;\n    var codeEl = pre.querySelector('code');\n    var lang = '';\n    if (codeEl) {\n      var m = (codeEl.className || '').match(/language-([\\w+-]+)/);\n      if (m) lang = m[1];\n    }\n    var wrap = document.createElement('div');\n    wrap.className = 'code-wrap';\n    pre.parentNode.insertBefore(wrap, pre);\n    wrap.appendChild(pre);\n\n    var head = document.createElement('div');\n    head.className = 'code-head';\n    var langSpan = document.createElement('span');\n    langSpan.className = 'lang';\n    langSpan.textContent = lang || 'code';\n    var copyBtn = document.createElement('button');\n    copyBtn.textContent = '复制';\n    copyBtn.onclick = function() {\n      var txt = codeEl ? codeEl.innerText : pre.innerText;\n      navigator.clipboard.writeText(txt).then(function() {\n        copyBtn.textContent = '已复制';\n        setTimeout(function(){ copyBtn.textContent = '复制'; }, 1500);\n      });\n    };\n    head.appendChild(langSpan);\n    head.appendChild(copyBtn);\n    wrap.insertBefore(head, pre);\n  });\n}\n\nvar currentUser = '', authToken = '', isRegisterMode = false, userState = null, providers = [];\nvar sending = false, abortCtrl = null, currentSessionForRename = null;\n\nfunction toast(msg, type) {\n  var el = document.createElement('div');\n  el.className = 'toast-item ' + (type || 'info');\n  el.textContent = msg;\n  document.getElementById('toast').appendChild(el);\n  setTimeout(function(){ el.remove(); }, 2500);\n}\n\nfunction toggleAuthMode() {\n  isRegisterMode = !isRegisterMode;\n  document.getElementById('auth-title').innerText = isRegisterMode ? '注册 LumaChat' : '登录 LumaChat';\n  document.getElementById('auth-btn').innerText = isRegisterMode ? '注 册' : '登 录';\n  document.getElementById('auth-switch').innerText = isRegisterMode ? '已有账号？去登录' : '没有账号？去注册';\n}\n\nasync function doAuth() {\n  var u = document.getElementById('auth-user').value.trim();\n  var p = document.getElementById('auth-pass').value;\n  if (!u || !p) return toast('请输入账号密码', 'err');\n  try {\n    var res = await fetch(isRegisterMode ? '/api/register' : '/api/login', {\n      method: 'POST', headers: {'Content-Type': 'application/json'},\n      body: JSON.stringify({username: u, password: p})\n    });\n    var data = await res.json();\n    if (!res.ok) return toast(data.message || '请求失败', 'err');\n    if (isRegisterMode) { toast('注册成功，请登录', 'ok'); toggleAuthMode(); }\n    else {\n      currentUser = data.data.username;\n      authToken = data.data.token;\n      document.getElementById('auth-modal').classList.add('hidden');\n      await initApp();\n    }\n  } catch(e) { toast('网络错误: ' + e.message, 'err'); }\n}\n\nasync function initApp() {\n  await loadUserState();\n  await loadProviders();\n  if (userState && userState.theme === 'dark') applyTheme(true);\n  document.getElementById('account-name').textContent = currentUser || '账户';\n}\n\nasync function loadUserState() {\n  var res = await fetch('/api/user/state', {headers: {'X-User': currentUser, 'Authorization': 'Bearer ' + authToken}});\n  if (!res.ok) return toast('登录状态失效', 'err');\n  userState = await res.json();\n  if (!userState.sessions) userState.sessions = {};\n  if (!userState.active_sess_id) userState.active_sess_id = Object.keys(userState.sessions)[0];\n  renderSessions();\n  renderChat();\n  syncPrefsUI();\n}\n\nasync function loadProviders() {\n  var res = await fetch('/api/providers', {headers: {'X-User': currentUser, 'Authorization': 'Bearer ' + authToken}});\n  providers = await res.json();\n  renderProvSelect();\n  renderProvList();\n}\n\nfunction renderProvSelect() {\n  var sel = document.getElementById('prov-select');\n  var cur = sel.value || (userState && userState.selected_prov);\n  sel.innerHTML = '';\n  if (!providers.length) { sel.innerHTML = '<option>无服务商</option>'; return; }\n  providers.forEach(function(p) {\n    var o = document.createElement('option');\n    o.value = p.name; o.textContent = p.name;\n    sel.appendChild(o);\n  });\n  if (cur && providers.some(function(p){ return p.name === cur; })) sel.value = cur;\n  renderModelSelect();\n}\n\nfunction renderModelSelect() {\n  var pName = document.getElementById('prov-select').value;\n  var prov = providers.find(function(p){ return p.name === pName; });\n  var mSel = document.getElementById('model-select');\n  var cur = mSel.value || (userState && userState.selected_model);\n  mSel.innerHTML = '';\n  if (!prov || !prov.models || !prov.models.length) { mSel.innerHTML = '<option>无模型</option>'; return; }\n  prov.models.forEach(function(m) {\n    var o = document.createElement('option'); o.value = m; o.textContent = m;\n    mSel.appendChild(o);\n  });\n  if (cur && prov.models.indexOf(cur) >= 0) mSel.value = cur;\n}\n\nfunction onProvChange() { renderModelSelect(); syncSettingsSilent(); }\nfunction onModelChange() { syncSettingsSilent(); }\n\nfunction renderSessions() {\n  var list = document.getElementById('session-list');\n  list.innerHTML = '';\n  if (!userState || !userState.sessions) return;\n  var ids = Object.keys(userState.sessions).sort(function(a,b) {\n    return (userState.sessions[b].updated_at || '').localeCompare(userState.sessions[a].updated_at || '');\n  });\n  ids.forEach(function(id) {\n    var s = userState.sessions[id];\n    var row = document.createElement('div');\n    row.className = 'session-row' + (id === userState.active_sess_id ? ' active' : '');\n    var title = document.createElement('span');\n    title.className = 'session-title';\n    title.textContent = s.title || '新对话';\n    row.appendChild(title);\n    var menu = document.createElement('button');\n    menu.className = 'session-menu';\n    menu.textContent = '⋮';\n    menu.onclick = function(e) { e.stopPropagation(); showSessionMenu(id, s.title); };\n    row.appendChild(menu);\n    row.onclick = function() { switchSession(id); };\n    list.appendChild(row);\n  });\n}\n\nfunction showSessionMenu(id, title) {\n  var action = prompt('操作（输入数字）：\\n1. 重命名\\n2. 清空消息\\n3. 删除会话', '1');\n  if (action === '1') {\n    currentSessionForRename = id;\n    document.getElementById('rename-input').value = title;\n    document.getElementById('rename-modal').classList.remove('hidden');\n  } else if (action === '2') {\n    if (confirm('确定清空该会话所有消息？')) clearSession(id);\n  } else if (action === '3') {\n    if (confirm('确定删除该会话？')) deleteSession(id);\n  }\n}\n\nfunction closeRename() { document.getElementById('rename-modal').classList.add('hidden'); }\n\nasync function confirmRename() {\n  var title = document.getElementById('rename-input').value.trim();\n  if (!title) return toast('标题不能为空', 'err');\n  await fetch('/api/session/rename', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({session_id: currentSessionForRename, title: title})});\n  userState.sessions[currentSessionForRename].title = title;\n  renderSessions(); closeRename();\n}\n\nasync function switchSession(id) {\n  if (sending) return toast('请等待当前回复结束', 'err');\n  if (id === userState.active_sess_id) return;\n  await fetch('/api/session/switch', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({session_id: id})});\n  userState.active_sess_id = id;\n  renderSessions(); renderChat();\n}\n\nasync function createSession() {\n  if (sending) return toast('请等待当前回复结束', 'err');\n  var res = await fetch('/api/session/new', {method: 'POST', headers: {'X-User': currentUser, 'Authorization': 'Bearer ' + authToken}});\n  var data = await res.json();\n  if (!res.ok) return toast(data.message || '创建失败', 'err');\n  userState.sessions[data.data.id] = data.data;\n  userState.active_sess_id = data.data.id;\n  renderSessions(); renderChat();\n}\n\nasync function deleteSession(id) {\n  if (sending) return toast('请等待当前回复结束', 'err');\n  var res = await fetch('/api/session/delete', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({session_id: id})});\n  var data = await res.json();\n  if (!res.ok) return toast(data.message || '删除失败', 'err');\n  delete userState.sessions[id];\n  if (userState.active_sess_id === id) {\n    userState.active_sess_id = Object.keys(userState.sessions)[0];\n  }\n  renderSessions(); renderChat();\n}\n\nasync function clearSession(id) {\n  await fetch('/api/session/clear', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({session_id: id})});\n  userState.sessions[id].messages = [];\n  userState.sessions[id].title = '新对话';\n  renderSessions(); renderChat();\n}\n\nfunction renderChat() {\n  var box = document.getElementById('chat-box');\n  box.innerHTML = '';\n  if (!userState) return;\n  var s = userState.sessions[userState.active_sess_id];\n  if (!s || !s.messages) { syncChatToggles(); return; }\n  document.getElementById('active-chat-title').textContent = s.title || '新对话';\n  s.messages.forEach(function(m){ appendMessageBubble(m.role, m.content); });\n  syncChatToggles();\n  box.scrollTop = box.scrollHeight;\n}\n\nfunction appendMessageBubble(role, content) {\n  var box = document.getElementById('chat-box');\n  var div = document.createElement('div');\n  div.className = 'msg ' + (role === 'user' ? 'user' : 'assistant');\n  if (role === 'user') {\n    div.textContent = content;\n  } else {\n    div.innerHTML = renderMarkdown(content);\n    decorateCodeBlocks(div);\n    var tools = document.createElement('div');\n    tools.className = 'msg-tools';\n    var copyBtn = document.createElement('button');\n    copyBtn.textContent = '⧉';\n    copyBtn.title = '复制';\n    copyBtn.onclick = function() { navigator.clipboard.writeText(content); toast('已复制', 'ok'); };\n    tools.appendChild(copyBtn);\n    div.appendChild(tools);\n  }\n  box.appendChild(div);\n  box.scrollTop = box.scrollHeight;\n  return div;\n}\n\nfunction syncChatToggles() {\n  var s = userState && userState.sessions[userState.active_sess_id];\n  var think = s && s.think_enabled != null ? !!s.think_enabled : !!(userState && !userState.disable_think);\n  var tokens = s && s.show_tokens != null ? !!s.show_tokens : !!(userState && userState.show_tokens);\n  var t = document.getElementById('chat-think-toggle'), k = document.getElementById('chat-token-toggle');\n  if (t) { t.classList.toggle('active', think); t.textContent = '✧ 思考模式：' + (think ? '开' : '关'); t.title = '本对话单独控制思考模式'; }\n  if (k) { k.classList.toggle('active', tokens); k.textContent = 'Token 统计：' + (tokens ? '开' : '关'); }\n}\nasync function persistSessionPrefs() {\n  var s = userState && userState.sessions[userState.active_sess_id]; if (!s) return;\n  var res = await fetch('/api/session/preferences', {method:'POST',headers:{'Content-Type':'application/json','X-User':currentUser,'Authorization':'Bearer '+authToken},body:JSON.stringify({session_id:s.id,think_enabled:s.think_enabled == null ? !userState.disable_think : !!s.think_enabled,show_tokens:s.show_tokens == null ? !!userState.show_tokens : !!s.show_tokens})});\n  if (!res.ok) toast('会话设置保存失败', 'err'); syncChatToggles();\n}\nfunction toggleChatThink() { var s=userState && userState.sessions[userState.active_sess_id]; if (!s) return; var current=s.think_enabled == null ? !userState.disable_think : !!s.think_enabled; s.think_enabled=!current; persistSessionPrefs(); }\nfunction toggleChatTokens() { var s=userState && userState.sessions[userState.active_sess_id]; if (!s) return; var cur=s.show_tokens == null ? !!userState.show_tokens : !!s.show_tokens; s.show_tokens=!cur; persistSessionPrefs(); }\nfunction toggleSidebar() { document.body.classList.toggle('sidebar-collapsed'); }\n\nfunction onKeyDown(e) {\n  if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {\n    e.preventDefault();\n    sendMessage();\n  }\n}\n\nfunction autoResize(el) {\n  el.style.height = 'auto';\n  el.style.height = Math.min(el.scrollHeight, 140) + 'px';\n}\n\nasync function sendMessage() {\n  if (sending) return;\n  var ta = document.getElementById('prompt-input');\n  var txt = ta.value.trim();\n  if (!txt) return;\n\n  var s = userState.sessions[userState.active_sess_id];\n  if (!s) return toast('无活动会话', 'err');\n\n  ta.value = '';\n  autoResize(ta);\n  sending = true;\n  document.getElementById('send-btn').disabled = true;\n\n  s.messages = s.messages || [];\n  s.messages.push({role: 'user', content: txt, timestamp: new Date().toISOString()});\n  if (s.title === '新对话' || !s.title) {\n    s.title = txt.length > 12 ? txt.slice(0, 12) + '...' : txt;\n    renderSessions();\n  }\n  renderChat();\n\n  var assistantDiv = appendMessageBubble('assistant', '');\n  assistantDiv.classList.add('dots');\n  var content = '';\n\n  abortCtrl = new AbortController();\n\n  try {\n    var res = await fetch('/api/chat', {\n      method: 'POST',\n      headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n      body: JSON.stringify({session_id: s.id, prompt: txt, think_enabled: (s.think_enabled == null ? !userState.disable_think : !!s.think_enabled), show_tokens: (s.show_tokens == null ? !!userState.show_tokens : !!s.show_tokens)}),\n      signal: abortCtrl.signal\n    });\n    if (!res.ok) {\n      var t = await res.text();\n      throw new Error(t || 'HTTP ' + res.status);\n    }\n\n    var reader = res.body.getReader();\n    var dec = new TextDecoder();\n    var buffer = '';\n    var evtName = 'message';\n    var dataLines = [];\n    var streamDone = false;\n\n    while (!streamDone) {\n      var r = await reader.read();\n      if (r.done) break;\n      buffer += dec.decode(r.value, {stream: true});\n      var idx;\n      while ((idx = buffer.indexOf('\\n\\n')) >= 0) {\n        var raw = buffer.slice(0, idx);\n        buffer = buffer.slice(idx + 2);\n        evtName = 'message';\n        dataLines = [];\n        raw.split('\\n').forEach(function(line) {\n          if (line.indexOf('event: ') === 0) evtName = line.slice(7);\n          else if (line.indexOf('data: ') === 0) dataLines.push(line.slice(6));\n        });\n        var data = dataLines.join('\\n');\n\n        if (data === '[DONE]') { streamDone = true; break; }\n\n        if (evtName === 'error') {\n          assistantDiv.classList.remove('dots');\n          assistantDiv.classList.add('error');\n          assistantDiv.textContent = '错误: ' + data;\n          s.messages.push({role: 'assistant', content: '[错误] ' + data});\n          streamDone = true;\n          break;\n        }\n        if (evtName === 'usage') {\n          var parts = data.split(',');\n          var p = parseInt(parts[0], 10) || 0;\n          var c = parseInt(parts[1], 10) || 0;\n          if (userState.show_tokens) {\n            var info = document.createElement('div');\n            info.className = 'token-info';\n            info.textContent = '📊 Token: 提示 ' + p + ' / 回复 ' + c + ' / 总计 ' + (p + c);\n            assistantDiv.appendChild(info);\n          }\n        }\n        if (evtName === 'message' || evtName === '') {\n          content += data;\n          assistantDiv.classList.remove('dots');\n          assistantDiv.innerHTML = renderMarkdown(content);\n          decorateCodeBlocks(assistantDiv);\n          document.getElementById('chat-box').scrollTop = 999999;\n        }\n      }\n    }\n\n    assistantDiv.classList.remove('dots');\n    if (content) {\n      s.messages.push({role: 'assistant', content: content, timestamp: new Date().toISOString()});\n    }\n    renderChat();\n  } catch(e) {\n    if (e.name === 'AbortError') {\n      toast('已停止', 'info');\n    } else {\n      assistantDiv.classList.remove('dots');\n      assistantDiv.classList.add('error');\n      assistantDiv.textContent = '请求失败: ' + e.message;\n      s.messages.push({role: 'assistant', content: '[请求失败] ' + e.message});\n    }\n  } finally {\n    sending = false;\n    abortCtrl = null;\n    document.getElementById('send-btn').disabled = false;\n  }\n}\n\nfunction openSettings() {\n  document.getElementById('settings-modal').classList.remove('hidden');\n  renderProvList();\n  syncProviderSettingsUI();\n  syncPrefsUI();\n  document.getElementById('acc-user').value = currentUser;\n  document.getElementById('account-name').textContent = currentUser || '账户';\n}\n\nfunction closeSettings() {\n  document.getElementById('settings-modal').classList.add('hidden');\n}\n\nfunction switchTab(name, btn) {\n  document.querySelectorAll('.tab').forEach(function(t){ t.classList.remove('active'); });\n  document.querySelectorAll('.tab-panel').forEach(function(p){ p.classList.remove('active'); });\n  btn.classList.add('active');\n  document.getElementById('tab-' + name).classList.add('active');\n  if (name === 'providers') renderProvList();\n}\n\nfunction renderProvList() {\n  var box = document.getElementById('prov-list');\n  box.innerHTML = '';\n  if (!providers.length) {\n    box.innerHTML = '<div class=\"empty\">暂无服务商，请到\"添加服务商\"标签添加</div>';\n    return;\n  }\n  providers.forEach(function(p) {\n    var item = document.createElement('div');\n    item.className = 'prov-item';\n    var modelList = p.models ? p.models.map(escapeHtml).join(', ') : '无';\n    var modelCount = p.models ? p.models.length : 0;\n    item.innerHTML =\n      '<div class=\"prov-item-head\">' +\n        '<span class=\"name\">' + escapeHtml(p.name) + '</span>' +\n        '<span class=\"badge\">' + modelCount + ' 模型</span>' +\n      '</div>' +\n      '<div class=\"prov-item-body\">' +\n        '<div>URL: ' + escapeHtml(p.base_url || '') + '</div>' +\n        '<div>Key: ' + escapeHtml(p.api_key || '') + '</div>' +\n        '<div>模型: ' + modelList + '</div>' +\n      '</div>' +\n      '<div class=\"prov-item-actions\">' +\n        '<button class=\"btn ghost sm edit-provider-btn\">编辑</button> ' + '<button class=\"btn danger sm\">删除</button>' +\n      '</div>';\n    var editBtn = item.querySelector('.edit-provider-btn');\n    editBtn.onclick = function() { editProvider(p.name); };\n    var delBtn = item.querySelector('.btn.danger');\n    delBtn.onclick = function() { deleteProvider(p.name); };\n    box.appendChild(item);\n  });\n}\n\nfunction editProvider(name) {\n  var p = providers.find(function(x){ return x.name === name; }); if (!p) return;\n  editingProviderName = p.name;\n  document.getElementById('add-name').value = p.name;\n  document.getElementById('add-url').value = p.base_url || '';\n  document.getElementById('add-key').value = '';\n  document.getElementById('add-key').placeholder = '留空则保留原 API Key';\n  var list = document.getElementById('model-list'); list.innerHTML = '';\n  (p.models || []).forEach(function(model){ var label=document.createElement('label'); label.className='model-option'; var cb=document.createElement('input'); cb.type='checkbox'; cb.className='model-chk'; cb.checked=true; cb.value=model; var span=document.createElement('span'); span.textContent=model; label.appendChild(cb); label.appendChild(span); list.appendChild(label); });\n  switchTab('add-provider', document.querySelector('.tab[onclick*=\\\"add-provider\\\"]'));\n  toast('正在编辑服务商：' + name, 'info');\n}\n\nfunction escapeHtml(s) {\n  return String(s || '').replace(/[&<>\"']/g, function(c){\n    return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c];\n  });\n}\n\nasync function deleteProvider(name) {\n  if (!confirm('确定删除服务商\"' + name + '\"？')) return;\n  var res = await fetch('/api/providers/delete', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({name: name})});\n  var data = await res.json();\n  if (!res.ok) return toast(data.message || '删除失败', 'err');\n  toast('已删除', 'ok');\n  await loadProviders();\n}\n\nasync function testProvider() {\n  var url = document.getElementById('add-url').value.trim();\n  var key = document.getElementById('add-key').value.trim();\n  if (!url) return toast('请填写 Base URL', 'err');\n  var res = await fetch('/api/providers/test', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({base_url: url, api_key: key})});\n  var data = await res.json();\n  if (!res.ok) return toast(data.message || '连接失败', 'err');\n  toast('连接成功', 'ok');\n}\n\nasync function fetchModels() {\n  var url = document.getElementById('add-url').value.trim();\n  var key = document.getElementById('add-key').value.trim();\n  if (!url) return toast('请填写 Base URL', 'err');\n  var list = document.getElementById('model-list');\n  list.innerHTML = '<div style=\"color:var(--sub);font-size:13px;text-align:center;padding:16px\">加载中...</div>';\n  var res = await fetch('/api/models/fetch', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({base_url: url, api_key: key})});\n  var models = await res.json();\n  if (!res.ok) { list.innerHTML = '<div class=\"empty\">获取失败</div>'; return; }\n  if (!models.length) { list.innerHTML = '<div class=\"empty\">未获取到模型</div>'; return; }\n  list.innerHTML = '';\n  models.forEach(function(m) {\n    var lbl = document.createElement('label');\n    lbl.className = 'model-item';\n    lbl.innerHTML = '<input type=\"checkbox\" class=\"model-chk\" value=\"' +\n      escapeHtml(m) + '\" checked> ' + escapeHtml(m);\n    list.appendChild(lbl);\n  });\n}\n\nasync function syncProviderSettingsUI() {\n  var ps=document.getElementById('settings-prov-select'), ms=document.getElementById('settings-model-select'); if(!ps||!ms) return;\n  ps.innerHTML=''; providers.forEach(function(p){var o=document.createElement('option');o.value=p.name;o.textContent=p.name;ps.appendChild(o)});\n  if(userState && userState.selected_prov && providers.some(function(p){return p.name===userState.selected_prov})) ps.value=userState.selected_prov;\n  fillSettingsModels(userState && userState.selected_model);\n}\nfunction fillSettingsModels(preferred) {\n  var ps=document.getElementById('settings-prov-select'), ms=document.getElementById('settings-model-select'); if(!ps||!ms) return;\n  var p=providers.find(function(x){return x.name===ps.value}); ms.innerHTML=''; (p&&p.models||[]).forEach(function(model){var o=document.createElement('option');o.value=model;o.textContent=model;ms.appendChild(o)});\n  if(preferred && p && p.models.indexOf(preferred)>=0) ms.value=preferred;\n}\nfunction onSettingsProvChange(){fillSettingsModels('');}\nfunction onSettingsModelChange(){}\n\nasync function saveAllSettings() {\n  var payload = {\n    selected_prov: document.getElementById('settings-prov-select').value,\n    selected_model: document.getElementById('settings-model-select').value,\n    show_tokens: document.getElementById('pref-show-tokens').checked,\n    disable_think: document.getElementById('pref-disable-think').checked,\n    disable_web: document.getElementById('pref-disable-web').checked\n  };\n  var settingsRes = await fetch('/api/user/settings', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify(payload)});\n  if (!settingsRes.ok) return toast('设置保存失败', 'err');\n  document.getElementById('prov-select').value = payload.selected_prov;\n  renderModelSelect();\n  document.getElementById('model-select').value = payload.selected_model;\n  userState.selected_prov = payload.selected_prov;\n  userState.selected_model = payload.selected_model;\n  userState.show_tokens = payload.show_tokens;\n  userState.disable_think = payload.disable_think;\n  userState.disable_web = payload.disable_web;\n  var darkMode = document.getElementById('pref-dark-theme').checked;\n  applyTheme(darkMode);\n  await fetch('/api/user/theme', {method:'POST',headers:{'Content-Type':'application/json','X-User':currentUser,'Authorization':'Bearer '+authToken},body:JSON.stringify({theme:darkMode?'dark':'light'})});\n  syncChatToggles();\n\n  var name = document.getElementById('add-name').value.trim();\n  var url = document.getElementById('add-url').value.trim();\n  var key = document.getElementById('add-key').value.trim();\n  var checked = Array.prototype.slice.call(document.querySelectorAll('.model-chk:checked')).map(function(c){ return c.value; });\n  if (name && url && checked.length) {\n    var res = await fetch(editingProviderName ? '/api/providers/update' : '/api/providers/add', {method: 'POST',\n      headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n      body: JSON.stringify(editingProviderName ? {original_name: editingProviderName, name: name, base_url: url, api_key: key, models: checked} : {name: name, base_url: url, api_key: key, models: checked})});\n    var data = await res.json();\n    if (!res.ok) return toast(data.message || '添加失败', 'err');\n    toast(editingProviderName ? '服务商已更新' : '服务商已添加', 'ok');\n    editingProviderName = '';\n    document.getElementById('add-key').placeholder = 'sk-...';\n    document.getElementById('add-name').value = '';\n    document.getElementById('add-url').value = '';\n    document.getElementById('add-key').value = '';\n    document.getElementById('model-list').innerHTML = '<div style=\"color:var(--sub);font-size:13px;text-align:center;padding:16px\">点击上方\"获取模型列表\"</div>';\n    await loadProviders();\n  }\n  toast('已保存', 'ok');\n  closeSettings();\n}\n\nasync function syncSettingsSilent() {\n  if (!userState) return;\n  var payload = {\n    selected_prov: document.getElementById('prov-select').value,\n    selected_model: document.getElementById('model-select').value,\n    show_tokens: userState.show_tokens,\n    disable_think: userState.disable_think,\n    disable_web: userState.disable_web\n  };\n  userState.selected_prov = payload.selected_prov;\n  userState.selected_model = payload.selected_model;\n  await fetch('/api/user/settings', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify(payload)});\n}\n\nfunction syncPrefsUI() {\n  if (!userState) return;\n  document.getElementById('pref-show-tokens').checked = !!userState.show_tokens;\n  document.getElementById('pref-dark-theme').checked = document.documentElement.getAttribute('data-theme') === 'dark';\n  document.getElementById('pref-disable-think').checked = !!userState.disable_think;\n  document.getElementById('pref-disable-web').checked = !!userState.disable_web;\n}\n\nasync function changePassword() {\n  var oldPass = document.getElementById('acc-old-pass').value;\n  var newPass = document.getElementById('acc-new-pass').value;\n  if (!oldPass || !newPass) return toast('请填写完整', 'err');\n  var res = await fetch('/api/user/password', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({old_password: oldPass, new_password: newPass})});\n  var data = await res.json();\n  if (!res.ok) return toast(data.message || '修改失败', 'err');\n  toast('密码已修改', 'ok');\n  document.getElementById('acc-old-pass').value = '';\n  document.getElementById('acc-new-pass').value = '';\n}\n\nfunction applyTheme(dark) {\n  document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');\n  \n  var link = document.querySelector('link[href*=\"highlight.js\"]');\n  if (link) link.href = dark\n    ? 'https://cdn.jsdelivr.net/npm/highlight.js@11.9.0/styles/github-dark.min.css'\n    : 'https://cdn.jsdelivr.net/npm/highlight.js@11.9.0/styles/github.min.css';\n}\n\nasync function toggleTheme() {\n  var dark = document.documentElement.getAttribute('data-theme') !== 'dark';\n  applyTheme(dark);\n  await fetch('/api/user/theme', {method: 'POST',\n    headers: {'Content-Type': 'application/json', 'X-User': currentUser, 'Authorization': 'Bearer ' + authToken},\n    body: JSON.stringify({theme: dark ? 'dark' : 'light'})});\n  if (userState) userState.theme = dark ? 'dark' : 'light';\n}\n\ndocument.addEventListener('keydown', function(e) {\n  if (e.ctrlKey && e.key === 'k') {\n    e.preventDefault();\n    document.getElementById('prompt-input').focus();\n  }\n  if (e.key === 'Escape') {\n    if (sending && abortCtrl) { abortCtrl.abort(); }\n    document.querySelectorAll('.modal:not(.hidden)').forEach(function(m){ m.classList.add('hidden'); });\n  }\n});\n</script>\n</body>\n</html>\n"
